"target\": \"ES2022\",\n    \"module\": \"ESNext\",\n    \"moduleResolution\": \"Bundler\",\n    \"lib\": [\"ES2022\"],\n    \"types\": [\"node\"],\n    \"strict\": true,\n    \"skipLibCheck\": true,\n    \"noEmit\": true,\n    \"verbatimModuleSyntax\": true\n  },\n  \"include\": [\"src/**/*.ts\", \"tsup.config.ts\", \"roadmap/**/*.ts\", \"scripts/generate-changelog-md.ts\"]\n}\n''',\n'tsup.config.ts': '''import { defineConfig } from 'tsup';\n\nexport default defineConfig({\n  entry: ['src/index.ts', 'src/cli.ts'],\n  format: ['esm'],\n  platform: 'node',\n  target: 'node22',\n  dts: true,\n  splitting: false,\n  sourcemap: false,\n  clean: true,\n});\n''',\n'src/index.ts': '''export function greet(name: string = 'world'): string {\n  if (typeof name !== 'string' || name.trim().length === 0) {\n    throw new TypeError('Name must be a nonblank string');\n  }\n  return `Hello, ${name}!`;\n}\n''',\n'src/cli.ts': '''#!/usr/bin/env node\nimport { greet } from './index.js';\n\nconst usage = 'Usage: greenfield-proof [name]\\\\n       greenfield-proof --help';\nconst args = process.argv.slice(2);\n\ntry {\n  if (args.length === 1 && args[0] === '--help') {\n    console.log(usage);\n  } else {\n    if (args.length > 1 || args.some((arg) => arg.startsWith('-'))) {\n      throw new TypeError('Expected one name and no unknown options');\n    }\n    console.log(greet(args[0]));\n  }\n} catch (error) {\n  console.error(error instanceof Error ? error.message : String(error));\n  console.error(usage);\n  process.exitCode = 1;\n}\n''',\n'test/api.test.mjs': '''import test from 'node:test';\nimport assert from 'node:assert/strict';\nimport { greet } from '../src/index.ts';\n\ntest('omitted and undefined names default to world', () => {\n  assert.equal(greet(), 'Hello, world!');\n  assert.equal(greet(undefined), 'Hello, world!');\n});\ntest('greets supplied names including Unicode', () => {\n  assert.equal(greet('Ada'), 'Hello, Ada!');\n  assert.equal(greet('\u4e16\u754c'), 'Hello, \u4e16\u754c!');\n});\ntest('preserves nonblank name characters', () => {\n  assert.equal(greet(' Ada '), 'Hello,  Ada !');\n});\ntest('rejects blank and nonstring names with TypeError', () => {\n  for (const name of ['', ' ', '\\\\t\\\\n', null, 42]) {\n    assert.throws(() => greet(name), TypeError);\n  }\n});\n''',\n'test/cli.test.mjs': '''import test from 'node:test';\nimport assert from 'node:assert/strict';\nimport { spawnSync } from 'node:child_process';\nimport { fileURLToPath } from 'node:url';\n\nconst cli = fileURLToPath(new URL('../src/cli.ts', import.meta.url));\nconst run = (...args) => {\n  const result = spawnSync(process.execPath, ['--import', 'tsx', cli, ...args], { encoding: 'utf8' });\n  assert.equal(result.error, undefined);\n  assert.equal(result.signal, null);\n  return result;\n};\ntest('CLI prints the default greeting', () => {\n  const result = run();\n  assert.equal(result.status, 0);\n  assert.equal(result.stdout, 'Hello, world!\\\\n');\n  assert.equal(result.stderr, '');\n});\ntest('CLI prints a supplied name', () => {\n  const result = run('Ada Lovelace');\n  assert.equal(result.status, 0);\n  assert.equal(result.stdout, 'Hello, Ada Lovelace!\\\\n');\n  assert.equal(result.stderr, '');\n});\ntest('help succeeds with usage and no greeting', () => {\n  const result = run('--help');\n  assert.equal(result.status, 0);\n  assert.equal(result.stdout, 'Usage: greenfield-proof [name]\\\\n       greenfield-proof --help\\\\n');\n  assert.equal(result.stderr, '');\n});\ntest('unknown options fail with usage', () => {\n  const result = run('--unknown');\n  assert.equal(result.status, 1);\n  assert.equal(result.stdout, '');\n  assert.match(result.stderr, /Usage: greenfield-proof/);\n});\ntest('blank names fail with usage', () => {\n  const result = run('   ');\n  assert.equal(result.status, 1);\n  assert.equal(result.stdout, '');\n  assert.match(result.stderr, /Name must be a nonblank string/);\n  assert.match(result.stderr, /Usage: greenfield-proof/);\n});\ntest('extra positional arguments fail with usage', () => {\n  const result = run('Ada', 'Grace');\n  assert.equal(result.status, 1);\n  assert.equal(result.stdout, '');\n  assert.match(result.stderr, /Usage: greenfield-proof/);\n});\n''',\n'docs/PRD.md': '''# Product requirements\n\n## Product\n\ngreenfield-proof is a small TypeScript reusable greeting API plus CLI for developers. The public behavior is specified in [UX canon](ux-canon.md).\n\n## Audience\n\nDevelopers importing a typed greeting function and invoking its CLI.\n\n## Platforms\n\nNode 22+ on Linux; the cached generator requires Node 22.12 or later on the selected runtime line.\n\n## Constraints\n\nUse npm, TypeScript, tsup and node:test. Private UNLICENSED fixture; no publishing or fixture commits. Adapt the cached create-vite 8.3.0 vanilla-ts scaffold directly in this repository. Preserve any present home byte-identically; stop if unexpected homes appear.\n\n## Non-goals\n\nNo framework runtime, external service, HTTP backend, authentication, mobile application, deployment, product remote or publishing. This API is an imported function, not a network service.\n\n## Success signals\n\nMeaningful API and CLI tests, typecheck, build, built CLI smoke, catalog comparison, roadmap config check, actual emission and the complete installed delivery validation suite pass. Simulation success does not imply a hosted CI run or deployment. A separate read-only brownfield re-audit follows execution.\n\n## Brand\n\nNon-Blade. No graphical UI. Registry absent/none because there are no UI components; no invented tokens, fonts or palette.\n\n## Decisions\n\n| Date | Ruling | Reason |\n| --- | --- | --- |\n| 2026-09-05 | Execute only after separate exact APPROVE GREENFIELD PLAN input | The preceding complete proposal is the path and command allowlist; this document is written only after that input. |\n| 2026-09-05 | [Technology stack](adr/0001-tech-stack.md) | User selected the library-cli archetype and minimal test dependencies. |\n| 2026-09-05 | [Non-UI design](adr/0002-design-system.md) | Product surface is an imported API and terminal CLI. |\n| 2026-09-05 | GitHub Actions; protected environment greenfield-validation; deployment provider none | Supplied delivery choices; no provider or deployment is available or authorized. |\n\n## Unknowns\n\nFuture distribution, HTTP services, graphical surfaces and credentials are unselected. No release date or live GitHub execution evidence is supplied. Revisit only through an approved scope change.\n''',\n'docs/adr/0001-tech-stack.md': '''# ADR 0001: Technology stack\n\n## Status\n\nAccepted after the separate greenfield plan approval.\n\n## Date\n\n2026-09-05\n\n## Context\n\nSee [product requirements](../PRD.md). The imported greeting API has no HTTP backend. Web, mobile, monorepo and backend matrices are therefore inapplicable.\n\n## Options: Library/CLI\n\nSource: installed zeroh-greenfield skills/stack-decision/references/matrices.md, Library/CLI section. Rows below are preserved verbatim.\n\n| option | pros | cons | better when | component reuse | source |\n| --- | --- | --- | --- | --- | --- |\n| tsup + node:test | Compact bundling with built-in tests | Two separate tools | Small TypeScript package values minimal test dependencies | Exported modules and fixtures | tsup |\n| tsdown + vitest | Modern bundling and rich tests | Additional test dependency | Vite-aligned libraries need fast test ergonomics | Exported modules and test helpers | tsdown |\n| unbuild | Convention-led library output | Less explicit build control | Multi-format package follows unjs conventions | Package presets and modules | unbuild |\n\n## Ruling\n\n2026-09-05: tsup + node:test, explicitly selected by the user for a small TypeScript reusable greeting API plus CLI with minimal test dependencies. Use npm, TypeScript and Node 22+ Linux. Adapt the library-cli manifest's my-lib destination to this scratch root using the approved cached create-vite entry, then remove its browser demo and Vite dependency.\n\n## Consequences\n\nKeep reusable logic in src/index.ts and process interaction in src/cli.ts. tsup and node:test remain separate tools. tsx loads TypeScript tests and vendored roadmap tooling with transform caching disabled. Direct versions are explicit and transitive versions are retained in package-lock.json. No framework runtime is installed. The fixture stays private and UNLICENSED.\n\n## Revisit when\n\nA second package needs workspace coordination, a supported runtime cannot consume ESM, or an approved requirement introduces a web, mobile or HTTP surface. Future distribution and service requirements remain unknown.\n''',\n'docs/adr/0002-design-system.md': '''# ADR 0002: Design system\n\n## Status\n\nAccepted after the separate greenfield plan approval.\n\n## Date\n\n2026-09-05\n\n## Context\n\nThe user selected a non-Blade API and terminal CLI, with no graphical UI. See [PRD](../PRD.md).\n\n## Options\n\nThe installed design-system reference's web and mobile component choices do not apply to a terminal-only product. The applicable supplied choice is no UI design system and registry absent/none. No visual alternative is inferred or selected.\n\n## Ruling\n\n2026-09-05: no UI design system; registry absent/none because there are no UI components. Do not invent tokens, fonts, palette or spacing. [UX canon](../ux-canon.md) owns terminal behavior. No Blade sibling handoff is needed.\n\n## Consequences\n\nNo component framework or design runtime dependency. Plain text, stdout/stderr and exit codes form the interaction contract. Future visual branding remains unknown.\n\n## Revisit when\n\nAn approved requirement adds the first graphical surface or Blade branding.\n''',\n'docs/CODE-STYLE.md': '''# Code style\n\n## Lint\n\nNone: no lint configuration or lint runner is selected. This is an approved absence, not a passing lint result.\n\n## Format\n\nNone: no formatter is configured. Follow the nearby TypeScript formatting and the sole repository conventions in [AGENTS.md](../AGENTS.md).\n\n## Types and tests\n\nThe strict compiler configuration is [tsconfig.json](../tsconfig.json); run npm run typecheck. Tests use node:test and node:assert/strict with real CLI subprocesses. Commands and lifecycle are maintained in [README](../README.md).\n''',\n'docs/architecture.md': '''# Architecture\n\n## Topic index\n\n| Topic | Home |\n| --- | --- |\n| Product boundaries and unknowns | [PRD](PRD.md) |\n| Stack and package boundary | [Technology ADR](adr/0001-tech-stack.md) |\n| Non-UI design ruling | [Design ADR](adr/0002-design-system.md) |\n| Terminal contract | [UX canon](ux-canon.md) |\n| Reusable greeting logic | [src/index.ts](../src/index.ts) |\n| Process adapter | [src/cli.ts](../src/cli.ts) |\n| Build boundary | [tsup.config.ts](../tsup.config.ts) |\n| Delivery execution contract | [Delivery config](../.github/greenfield-delivery.json) |\n| Roadmap gates and pointers | [Roadmap config](../roadmap/roadmap.config.json) |\n\n## Extend protocol\n\nKeep greeting logic independent of process I/O. Extend the public contract and its behavior tests together. Record an approved boundary change in the owning ADR before introducing another package or service. Consumer tooling resolves local homes; it does not assume a plugin-internal filesystem path.\n''',\n'docs/ux-canon.md': '''# UX canon\n\n## Visual language\n\nPlain terminal text. Fonts, palette, spacing and visual tokens are inapplicable.\n\n## Component vocabulary\n\nAn imported greet(name?: string) function and the greenfield-proof CLI. No graphical components or registry.\n\n## Interaction rules\n\ngreet() and greet(undefined) return Hello, world!. A supplied nonblank string returns Hello, <name>! with its characters preserved. Empty or whitespace-only names throw TypeError; nonstring JavaScript inputs also throw TypeError.\n\nThe CLI accepts zero or one name and prints the greeting plus a newline to stdout. The sole --help argument prints usage to stdout and exits 0. Unknown options, extra arguments and blank names print an error and usage to stderr, print no greeting, and exit 1. Successful greetings exit 0. Usage is:\n\n    Usage: greenfield-proof [name]\n           greenfield-proof --help\n\n## Binding design system\n\nNone, as ruled in [ADR 0002](adr/0002-design-system.md). Non-Blade; registry absent/none because there is no UI. Do not introduce visual tokens without a new approved requirement.\n''',\n'docs/third-party.md': '''# Third-party sources\n\n| Source | License | Placement |\n| --- | --- | --- |\n| create-vite 8.3.0 cached public generator; published archive SHA1 4addb78fe6f996a8f8c12a8e9bda1bff37e18baf | MIT; Allowed anywhere | Generation only; browser demo removed |\n| tsup 8.5.0, https://tsup.egoist.dev/ | MIT; Allowed anywhere | Development build tooling |\n| TypeScript 5.9.3 | Apache-2.0; Allowed anywhere | Development compiler |\n| tsx 4.23.12 | MIT; Allowed anywhere | Development test and roadmap loader |\n| zod 4.4.3 | MIT; Allowed anywhere | Vendored roadmap tooling dependency |\n| @types/node 22.15.30 | MIT; Allowed anywhere | Development declarations |\n| node:test, https://nodejs.org/api/test.html | Node runtime license | Built-in test runner |\n| zeroh-greenfield 1.0.0 templates and zeroh-roadmap 0.39.1 scaffold | Apache-2.0; Allowed anywhere | Consumer-owned repository tooling |\n\nThe copied Apache license is [retained here](licenses/APACHE-2.0.txt). Workflow action pins and their version comments remain in the canonical copied workflows. The release workflow changes only its protected-environment placeholder. The roadmap configuration changes its generated plugin schema pointer to the copied consumer schema. Original fixture code remains private and UNLICENSED; nothing is published.\n''',\n'AGENTS.md': '''# Repository guidance\n\n## Conventions\n\nKeep reusable behavior in src/index.ts and process I/O in src/cli.ts. Use strict TypeScript and node:test with node:assert/strict. Exercise CLI behavior through real subprocesses. README owns runnable command guidance; roadmap/roadmap.config.json owns gate bindings. Product, architecture and UX facts remain in their linked independent docs homes.\n\n## Don't\n\nDo not introduce a framework runtime, external service, authentication, mobile UI, product remote, publishing or deployment. Do not invent design tokens or duplicate conventions into harness files. Do not assume plugin-internal paths in consumer code. Do not commit inside this native fixture.\n\n## Generalize-forward\n\nExtract a shared abstraction when a second real consumer needs the same behavior; preserve the small API/process boundary until then.\n\n## Flag-first delivery\n\nFuture user-facing behavior changes require an explicit flag lifecycle or an approved justification that a flag is inapplicable. Keep new flags disabled until their rollout is approved. Keep release-only work in hold[]; this fixture authorizes no release or deployment.\n\n## Planning\n\nUse the installed zeroh-roadmap phase workflow for subsequent development. Preserve existing homes and generated harness blocks byte-identically unless an exact repair is separately approved.\n''',\n'CLAUDE.md': '''@AGENTS.md\n\nUse AGENTS.md as the sole conventions home. Keep harness-specific guidance here only.\n''',\n'CONTRIBUTING.md': '''# Contributing\n\nFollow [AGENTS.md](AGENTS.md). Use concise imperative commit subjects in ordinary repositories; commits are forbidden in this native fixture.\n\nRun the commands in [README](README.md). Add behavior tests when the public contract changes. Keep documentation clear, concise, current and linked to one authoritative home per fact. Standalone ADRs describe approved boundary decisions.\n''',\n'README.md': '''# greenfield-proof\n\nA private TypeScript greeting API and CLI for developers. See [product requirements](docs/PRD.md) and the [CLI contract](docs/ux-canon.md).\n\n## Structure\n\n| Path | Purpose |\n| --- | --- |\n| src/index.ts | Reusable greeting API |\n| src/cli.ts | Executable process adapter |\n| test/ | API and real CLI subprocess tests |\n| tsup.config.ts | ESM build and declarations |\n| dist/ | Built API and CLI outputs |\n| docs/ | Product, ADR, standards, architecture and UX homes |\n| roadmap/ | Vendored roadmap tooling, config, phases and arcs |\n| reviews/ | Emitted changelog and release review home |\n| scripts/ | Copied catalog, delivery and review tooling |\n| .github/greenfield-delivery.json | Complete delivery execution contract |\n| .github/workflows/ci.yml | Affected/local/full test lifecycle and authoritative backstop |\n| .github/workflows/release.yml | Exact-artifact release verification; promotion unavailable |\n\n## Commands\n\nUse Node 22.12+ on Linux. npm commands use npm_config_cache=$PWD/.npm-cache and npm_config_logs_dir=$PWD/.npm-logs so caches stay local.\n\n| Command | Purpose |\n| --- | --- |\n| npm ci --no-audit --no-fund | Install the retained lockfile |\n| npm run typecheck | Check source, build config and roadmap types |\n| npm test | Full local API and CLI behavior suite |\n| npm run build | Build dist with tsup |\n| node dist/cli.js --help | Built CLI smoke check |\n| npm run emit:phases | Emit reviews/changelog.json |\n| npm run changelog:md | Optional later Markdown changelog generation |\n| node scripts/ci-shard-plan.mjs affected | PR checks; requires the real BASE_SHA and deliberately runs full tests |\n\nThe installed catalog checker is scripts/check-readme-catalog.mjs, bound to project-root mode with source dot and project name greenfield-proof. Lint and browser e2e are explicitly absent; they are not passing gates.\n\n## Delivery\n\n.github/workflows/ci.yml runs the full small suite for PRs because no dependency-aware selector exists. Main and manual runs inventory real tracked test files, shard exactly once, merge actual JUnit and LCOV, build once and produce authoritative evidence. Nightly runs diagnose without authoritative r